output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts must not be taken into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_walkin_aisle",
    "text": "Before entering a narrow walk-in aisle, a shopper must not still be pushing a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enter_single_file_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "single_file_shelf_aisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_with_cart"
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "A cart parked at a walk-in aisle mouth must be reclaimed before the shopper leaves.",
    "abstraction": {
      "state_properties": {
        "walkin_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "park_cart_at_mouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "walkin_aisle_mouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "reclaim_cart_at_mouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "walkin_aisle_mouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart_at_mouth",
      "discharge": "reclaim_cart_at_mouth"
    }
  },
  {
    "id": "cart_free_travel_only_in_pedestrian_zones",
    "text": "After leaving the cart bay, cart-free movement is only acceptable in designated pedestrian walk-in aisles and their mouths.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_bay_zone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "single_file_walkin_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "walkin_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cart_free_allowed_zone": {
          "or": [
            "entrance_cart_bay_zone",
            "single_file_walkin_aisle",
            "walkin_aisle_mouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          {
            "not": "cart_free_allowed_zone"
          }
        ]
      }
    }
  },
  {
    "id": "must_take_cart_from_station",
    "text": "A shopper must collect a cart from the cart station before continuing through the store.",
    "abstraction": {
      "state_properties": {
        "cart_station": "at(1,7)"
      },
      "events": {
        "take_cart_from_station": {
          "pre": {
            "and": [
              "cart_station",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_station"
    }
  },
  {
    "id": "one_way_no_westbound",
    "text": "Aisle circulation is one-way, so shoppers must not travel west.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "W"
    }
  },
  {
    "id": "cart_required_for_open_shelf_service",
    "text": "Shelf interactions in open cart-accessible aisles must be performed while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "open_shelf_service_area": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_shelf_aisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "open_shelf_service_area",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_handling_only_at_approved_sites",
    "text": "Carts may only be picked up or put down at the cart station or at marked walk-in aisle mouths.",
    "abstraction": {
      "state_properties": {
        "cart_station": "at(1,7)",
        "walkin_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "approved_cart_handling_site": {
          "or": [
            "cart_station",
            "walkin_aisle_mouth"
          ]
        }
      },
      "events": {
        "put_down_cart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pick_up_cart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "put_down_cart",
              "pick_up_cart"
            ]
          },
          {
            "not": "approved_cart_handling_site"
          }
        ]
      }
    }
  }
]
